try:
    print('>>> f = delattr')
    print('>>> x = b""')
    print('>>> y = 1j')
    print('>>> f(x, y)')
    f = delattr
    x = b""
    y = 1j
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
